def check_dict_case(dict):
    if not dict:
        return False
    lower_case, upper_case = True, True
    for key in dict:
        if not isinstance(key, str):
            return False
        if lower_case and not key.islower():
            lower_case = False
        if upper_case and not key.isupper():
            upper_case = False
        if not lower_case and not upper_case:
            return False
    return lower_case or upper_case
