def check_dict_case(dict):
    if not dict:
        return False
    keys = list(dict.keys())
    if not all(isinstance(k, str) for k in keys):
        return False
    if all(k.islower() for k in keys):
        return True
    if all(k.isupper() for k in keys):
        return True
    return False
